import XCTest
@testable import CryptoResearch
final class ServerOperationsTests:XCTestCase {
 func testBoundedRoutes(){for path in ["api/v1/diagnostics","api/v1/events?limit=50","api/v1/events?limit=50&before=9223372036854775807","api/v1/sessions?limit=100","api/v1/sessions/"+String(repeating:"a",count:32)+"/report"]{XCTAssertTrue(PaperServerAPI.allowedPath(path))};for path in ["api/v1/orders","api/v1/events?limit=50&before=0","api/v1/events?limit=50&before=9223372036854775808","api/v1/events?limit=50&before=1&token=x","api/v1/sessions/../report","api/v1/sessions/"+String(repeating:"a",count:32)+"/report\n"]{XCTAssertFalse(PaperServerAPI.allowedPath(path))}}
 @MainActor func testDiagnosticAndLiveModeRejection()throws{let store=ServerOperationsStore(base:"",token:"");let raw="{\"mode\":\"SERVER_PAPER_ONLY\",\"version\":\"1.4.0\",\"live_orders_supported\":false,\"uptime_seconds\":12,\"feed_frames\":8,\"feed_reconnects\":2,\"database_bytes\":4096,\"workers\":{\"clock\":\"failed\"},\"session_state\":\"paused\"}";try store.apply("api/v1/diagnostics",data:Data(raw.utf8));XCTAssertEqual(store.diagnostic?.workers["clock"],"failed");XCTAssertThrowsError(try store.apply("api/v1/diagnostics",data:Data(raw.replacingOccurrences(of:"false",with:"true").utf8)))}
 @MainActor func testEventAndArchiveDecode()throws{let store=ServerOperationsStore(base:"",token:"");let raw="{\"items\":[{\"id\":9,\"created_ms\":1767225600000,\"kind\":\"worker_failed\",\"detail\":\"fake worker\"}],\"next_before\":9}";try store.apply("api/v1/events?limit=50",data:Data(raw.utf8));XCTAssertEqual(store.events.first?.title,"서버 작업 중단");XCTAssertEqual(store.nextBefore,9);try store.apply("api/v1/sessions?limit=100",data:Data("{\"items\":[{\"session_id\":\"a\",\"symbol\":\"BTC\",\"archived_at\":1767225600}]}".utf8));XCTAssertEqual(store.sessions.first?.symbol,"BTC")}
 @MainActor func testMissingConfigurationStaysOffline(){let store=ServerOperationsStore(base:"",token:"");store.load("api/v1/diagnostics");XCTAssertFalse(store.busy);XCTAssertNil(store.received);XCTAssertTrue(store.message.contains("저장"));store.cancel()}
}
